11	// intentWorld 建立 alice（持有人/创作者）、bob、carol、dave 四个可用账户，
12	// 并向 alice 发行藏品 i1（持有版本 1）。
13	func intentWorld(t *testing.T, r *Registry) {
14		t.Helper()
15		setupWorld(t, r)
16		for _, id := range []string{"carol", "dave"} {
17			if err := r.RegisterAccount(id, "参与人"); err != nil {
18				t.Fatal(err)
19			}
20		}
21		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
22			t.Fatal(err)
23		}
24	}
