34	func createIntentReq(r *Registry, id string) CreateSplitIntentRequest {
35		return CreateSplitIntentRequest{
36			Operator: "alice", Reason: "协商拆分", RequestID: "create-" + id,
37			IntentID: id, ItemID: "i1", ExpectedOwner: "alice", ExpectedVer: 1,
38			ExpiresAt: r.now().Add(time.Hour), Shares: intentShares(),
39		}
40	}
