42	func answerReq(op, intentID, rid string, agree bool) AnswerSplitIntentRequest {
43		return AnswerSplitIntentRequest{
44			Operator: op, Reason: "答复方案", RequestID: rid,
45			IntentID: intentID, Agree: agree,
46		}
47	}
