49	func withdrawReq(op, intentID, rid string) WithdrawSplitIntentRequest {
50		return WithdrawSplitIntentRequest{
51			Operator: op, Reason: "撤回意向", RequestID: rid, IntentID: intentID,
52		}
53	}
