57	func TestCreateSplitIntent(t *testing.T) {
58		r := mustCreate(t, tempDir(t))
59		intentWorld(t, r)
60	
61		res, err := r.CreateSplitIntent(createIntentReq(r, "sp1"))
62		if err != nil {
63			t.Fatalf("CreateSplitIntent: %v", err)
64		}
65		if res.Status != SplitPending || res.GrantVer != 1 || res.Replayed {
66			t.Fatalf("unexpected create result: %+v", res)
67		}
68		in, err := r.GetSplitIntent("sp1")
69		if err != nil {
70			t.Fatal(err)
71		}
72		if in.ItemID != "i1" || in.InitiatorID != "alice" || in.GrantVer != 1 ||
73			in.Status != SplitPending || len(in.Shares) != 3 {
74			t.Fatalf("intent content wrong: %+v", in)
75		}
76		// 份额按账户排序保存；发起人列入方案，创建时视为已同意
77		want := []SplitParty{
78			{AccountID: "alice", Share: 5000, Answer: SplitAnswerAgree},
79			{AccountID: "bob", Share: 3000},
80			{AccountID: "carol", Share: 2000},
81		}
82		for i, p := range in.Shares {
83			if p != want[i] {
84				t.Fatalf("party %d wrong: %+v want %+v", i, p, want[i])
85			}
86		}
87		// 意向不改变持有关系与藏品历史
88		h, _ := r.GetHolding("i1")
89		if h.OwnerID != "alice" || h.Version != 1 {
90			t.Fatalf("creating intent must not change holding: %+v", h)
91		}
92		hist, _ := r.History("i1")
93		if len(hist) != 1 {
94			t.Fatalf("create intent must not add item history: %d", len(hist))
95		}
96		// 创建事件
97		evs, err := r.SplitIntentHistory("i1")
98		if err != nil || len(evs) != 1 {
99			t.Fatalf("intent history: %v %v", evs, err)
100		}
101		if e := evs[0]; e.Kind != "create" || e.IntentID != "sp1" || e.Operator != "alice" ||
102			e.Reason != "协商拆分" || e.RequestID != "create-sp1" ||
103			e.FromStatus != "" || e.ToStatus != SplitPending || e.OccurredAt.IsZero() {
104			t.Fatalf("create event wrong: %+v", e)
105		}
106	}
