108	func TestCreateSplitIntentValidation(t *testing.T) {
109		r := mustCreate(t, tempDir(t))
110		intentWorld(t, r)
111	
112		// 必填缺失
113		if _, err := r.CreateSplitIntent(CreateSplitIntentRequest{}); !errors.Is(err, ErrInvalidArgument) {
114			t.Fatalf("empty request: %v", err)
115		}
116		base := createIntentReq(r, "sp1")
117		// 账户少于两个
118		bad := base
119		bad.Shares = []SplitShare{{AccountID: "alice", Share: 10000}}
120		if _, err := r.CreateSplitIntent(bad); !errors.Is(err, ErrInvalidArgument) {
121			t.Fatalf("single party: %v", err)
122		}
123		// 账户重复
124		bad = base
125		bad.Shares = []SplitShare{{AccountID: "bob", Share: 5000}, {AccountID: "bob", Share: 5000}}
126		if _, err := r.CreateSplitIntent(bad); !errors.Is(err, ErrInvalidArgument) {
127			t.Fatalf("dup account: %v", err)
128		}
129		// 份额越界
130		for _, share := range []int64{0, -1, 10001} {
131			bad = base
132			bad.Shares = []SplitShare{{AccountID: "bob", Share: share}, {AccountID: "carol", Share: 10000 - share}}
133			if _, err := r.CreateSplitIntent(bad); !errors.Is(err, ErrInvalidArgument) {
134				t.Fatalf("share %d: %v", share, err)
135			}
136		}
137		// 合计不为 10000
138		bad = base
139		bad.Shares = []SplitShare{{AccountID: "bob", Share: 5000}, {AccountID: "carol", Share: 4999}}
140		if _, err := r.CreateSplitIntent(bad); !errors.Is(err, ErrInvalidArgument) {
141			t.Fatalf("total 9999: %v", err)
142		}
143		// 到期时间不晚于当前时间
144		bad = base
145		bad.ExpiresAt = r.now().Add(-time.Minute)
146		if _, err := r.CreateSplitIntent(bad); !errors.Is(err, ErrInvalidArgument) {
147			t.Fatalf("past expiry: %v", err)
148		}
149		// 参数错误不占用请求号：同一请求号修正后可正常执行
150		good := base
151		good.RequestID = "create-sp1"
152		if _, err := r.CreateSplitIntent(good); err != nil {
153			t.Fatalf("request id must not be consumed by invalid params: %v", err)
154		}
155	}
