168		req = createIntentReq(r, "sp1")
169		req.Operator = "ghost"
170		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrNotFound) {
171			t.Fatalf("unknown operator: %v", err)
172		}
173		// 参与账户未登记
174		req = createIntentReq(r, "sp1")
175		req.Shares = []SplitShare{{AccountID: "bob", Share: 5000}, {AccountID: "ghost", Share: 5000}}
176		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrNotFound) {
177			t.Fatalf("unknown party: %v", err)
178		}
