185	func TestCreateSplitIntentStateRejections(t *testing.T) {
186		r := mustCreate(t, tempDir(t))
187		intentWorld(t, r)
188	
189		// 参与账户停用
190		if err := r.DeactivateAccount("carol"); err != nil {
191			t.Fatal(err)
192		}
193		req := createIntentReq(r, "sp1")
194		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrAccountInactive) {
195			t.Fatalf("inactive party: %v", err)
196		}
197		// 状态类拒绝占用请求号：相同参数重提回放首次拒绝
198		res, err := r.CreateSplitIntent(req)
199		if !errors.Is(err, ErrAccountInactive) || !res.Replayed {
200			t.Fatalf("replayed rejection: %+v %v", res, err)
201		}
202		// 账户恢复可用不可能（停用是终态），换请求号与方案继续
203		if err := r.RegisterAccount("erin", "替补"); err != nil {
204			t.Fatal(err)
205		}
206		req = createIntentReq(r, "sp1")
207		req.RequestID = "create-sp1b"
208		req.Shares = []SplitShare{{AccountID: "bob", Share: 5000}, {AccountID: "erin", Share: 5000}}
209		if _, err := r.CreateSplitIntent(req); err != nil {
210			t.Fatalf("create with active parties: %v", err)
211		}
212		// 意向编号已用
213		activeShares := []SplitShare{{AccountID: "bob", Share: 5000}, {AccountID: "erin", Share: 5000}}
214		req = createIntentReq(r, "sp1")
215		req.RequestID = "create-dup"
216		req.Shares = activeShares
217		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrAlreadyExists) {
218			t.Fatalf("duplicate intent id: %v", err)
219		}
220		// 持有版本不符（状态类拒绝占用请求号，后续各例换新请求号）
221		req = createIntentReq(r, "sp2")
222		req.Shares = activeShares
223		req.ExpectedVer = 7
224		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrConflict) {
225			t.Fatalf("version mismatch: %v", err)
226		}
227		// 期望持有人不符
228		req = createIntentReq(r, "sp2")
229		req.RequestID = "create-sp2b"
230		req.Shares = activeShares
231		req.ExpectedOwner = "bob"
232		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrConflict) {
233			t.Fatalf("owner mismatch: %v", err)
234		}
235		// 非持有人发起
236		req = createIntentReq(r, "sp2")
237		req.RequestID = "create-sp2c"
238		req.Operator = "bob"
239		req.Shares = activeShares
240		if _, err := r.CreateSplitIntent(req); !errors.Is(err, ErrConflict) {
241			t.Fatalf("non-holder operator: %v", err)
242		}
243	}
