281	func TestAnswerSplitIntent(t *testing.T) {
282		r := mustCreate(t, tempDir(t))
283		intentWorld(t, r)
284		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp1")); err != nil {
285			t.Fatal(err)
286		}
287	
288		// bob 同意：仍为待确认（carol 未答复）
289		res, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", true))
290		if err != nil || res.Status != SplitPending {
291			t.Fatalf("bob agree: %+v %v", res, err)
292		}
293		// 重复相同答复（新请求号）：成功但不新增记录
294		res, err = r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob-2", true))
295		if err != nil || res.Status != SplitPending || res.Replayed {
296			t.Fatalf("repeat same answer: %+v %v", res, err)
297		}
298		evs, _ := r.SplitIntentHistory("i1")
299		if len(evs) != 2 { // create + 首次答复
300			t.Fatalf("repeat answer must not add event: %d", len(evs))
301		}
302		// 改答拒绝
303		if _, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob-3", false)); !errors.Is(err, ErrSplitAnswered) {
304			t.Fatalf("change answer: %v", err)
305		}
306		// 名单外账户无权答复
307		if _, err := r.AnswerSplitIntent(answerReq("dave", "sp1", "ans-dave", true)); !errors.Is(err, ErrForbidden) {
308			t.Fatalf("outsider answer: %v", err)
309		}
310		// 发起人创建时已视为同意，改答拒绝
311		if _, err := r.AnswerSplitIntent(answerReq("alice", "sp1", "ans-alice", false)); !errors.Is(err, ErrSplitAnswered) {
312			t.Fatalf("initiator change answer: %v", err)
313		}
314		// carol 同意：全部同意，已达成
315		res, err = r.AnswerSplitIntent(answerReq("carol", "sp1", "ans-carol", true))
316		if err != nil || res.Status != SplitAgreed {
317			t.Fatalf("carol agree: %+v %v", res, err)
318		}
319		in, _ := r.GetSplitIntent("sp1")
320		if in.Status != SplitAgreed {
321			t.Fatalf("status must be agreed: %+v", in)
322		}
323		// 答复事件：首次答复记录操作者、请求号与前后状态
324		evs, _ = r.SplitIntentHistory("i1")
325		if len(evs) != 3 {
326			t.Fatalf("want 3 events, got %d", len(evs))
327		}
328		if e := evs[1]; e.Kind != "answer" || e.Operator != "bob" || e.Answer != SplitAnswerAgree ||
329			e.RequestID != "ans-bob" || e.FromStatus != SplitPending || e.ToStatus != SplitPending {
330			t.Fatalf("bob answer event wrong: %+v", e)
331		}
332		if e := evs[2]; e.Kind != "answer" || e.Operator != "carol" ||
333			e.FromStatus != SplitPending || e.ToStatus != SplitAgreed {
334			t.Fatalf("carol answer event wrong: %+v", e)
335		}
336		// 已达成且有效时重复相同答复仍成功
337		res, err = r.AnswerSplitIntent(answerReq("carol", "sp1", "ans-carol-2", true))
338		if err != nil || res.Status != SplitAgreed {
339			t.Fatalf("repeat after agreed: %+v %v", res, err)
340		}
341		// 已达成仍阻止另建意向
342		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp2")); !errors.Is(err, ErrConflict) {
343			t.Fatalf("agreed intent must block new intent: %v", err)
344		}
345	}
