347	func TestAnswerSplitIntentReject(t *testing.T) {
348		r := mustCreate(t, tempDir(t))
349		intentWorld(t, r)
350		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp1")); err != nil {
351			t.Fatal(err)
352		}
353	
354		res, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", false))
355		if err != nil || res.Status != SplitRejected {
356			t.Fatalf("bob reject: %+v %v", res, err)
357		}
358		in, _ := r.GetSplitIntent("sp1")
359		if in.Status != SplitRejected || in.EndedAt.IsZero() {
360			t.Fatalf("intent must be rejected: %+v", in)
361		}
362		// 已拒绝不再接受答复
363		if _, err := r.AnswerSplitIntent(answerReq("carol", "sp1", "ans-carol", true)); !errors.Is(err, ErrSplitIntentRejected) {
364			t.Fatalf("answer after reject: %v", err)
365		}
366		// 已拒绝不能撤回
367		if _, err := r.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-1")); !errors.Is(err, ErrSplitIntentRejected) {
368			t.Fatalf("withdraw rejected: %v", err)
369		}
370		// 已结束的意向仍可查询，且可用新编号另建方案
371		evs, _ := r.SplitIntentHistory("i1")
372		if len(evs) != 2 || evs[1].ToStatus != SplitRejected {
373			t.Fatalf("reject event wrong: %+v", evs)
374		}
375		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp2")); err != nil {
376			t.Fatalf("new intent after reject: %v", err)
377		}
378	}
