382	func TestWithdrawSplitIntent(t *testing.T) {
383		r := mustCreate(t, tempDir(t))
384		intentWorld(t, r)
385		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp1")); err != nil {
386			t.Fatal(err)
387		}
388	
389		// 仅发起人可撤回
390		if _, err := r.WithdrawSplitIntent(withdrawReq("bob", "sp1", "wd-bob")); !errors.Is(err, ErrForbidden) {
391			t.Fatalf("non-initiator withdraw: %v", err)
392		}
393		res, err := r.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-1"))
394		if err != nil || res.Status != SplitWithdrawn {
395			t.Fatalf("withdraw: %+v %v", res, err)
396		}
397		in, _ := r.GetSplitIntent("sp1")
398		if in.Status != SplitWithdrawn || in.EndedAt.IsZero() {
399			t.Fatalf("intent must be withdrawn: %+v", in)
400		}
401		evs, _ := r.SplitIntentHistory("i1")
402		if len(evs) != 2 {
403			t.Fatalf("want 2 events, got %d", len(evs))
404		}
405		if e := evs[1]; e.Kind != "withdraw" || e.Operator != "alice" ||
406			e.RequestID != "wd-1" || e.FromStatus != SplitPending || e.ToStatus != SplitWithdrawn {
407			t.Fatalf("withdraw event wrong: %+v", e)
408		}
409		// 已撤回再次撤回成功但不增加记录
410		res, err = r.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-2"))
411		if err != nil || res.Status != SplitWithdrawn {
412			t.Fatalf("re-withdraw: %+v %v", res, err)
413		}
414		evs, _ = r.SplitIntentHistory("i1")
415		if len(evs) != 2 {
416			t.Fatalf("re-withdraw must not add event: %d", len(evs))
417		}
418		// 已撤回不再接受答复
419		if _, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", true)); !errors.Is(err, ErrSplitIntentWithdrawn) {
420			t.Fatalf("answer after withdraw: %v", err)
421		}
422	}
