426	func TestSplitIntentInvalidOnTransfer(t *testing.T) {
427		r := mustCreate(t, tempDir(t))
428		intentWorld(t, r)
429		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp1")); err != nil {
430			t.Fatal(err)
431		}
432	
433		// 持有版本变化后意向失效
434		if _, err := r.Transfer(xferReq("alice", "i1", "bob", 1, "t-1")); err != nil {
435			t.Fatal(err)
436		}
437		in, _ := r.GetSplitIntent("sp1")
438		if in.Status != SplitInvalid {
439			t.Fatalf("intent must be invalid after transfer: %+v", in)
440		}
441		if _, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", true)); !errors.Is(err, ErrSplitIntentInvalid) {
442			t.Fatalf("answer on invalid: %v", err)
443		}
444		if _, err := r.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-1")); !errors.Is(err, ErrSplitIntentInvalid) {
445			t.Fatalf("withdraw on invalid: %v", err)
446		}
447		// 藏品转回原持有人也不能恢复
448		if _, err := r.Transfer(xferReq("bob", "i1", "alice", 2, "t-2")); err != nil {
449			t.Fatal(err)
450		}
451		in, _ = r.GetSplitIntent("sp1")
452		if in.Status != SplitInvalid {
453			t.Fatalf("transfer back must not restore intent: %+v", in)
454		}
455		// 失效后可用新编号另建方案
456		req := createIntentReq(r, "sp2")
457		req.ExpectedVer = 3
458		if _, err := r.CreateSplitIntent(req); err != nil {
459			t.Fatalf("new intent after invalid: %v", err)
460		}
461	}
