483		}
484		if _, err := r.CreateSplitIntent(req); err != nil {
485			t.Fatalf("new intent after invalid: %v", err)
486		}
487		if err := r.DeactivateAccount("alice"); err != nil {
488			t.Fatal(err)
489		}
490		in, _ = r.GetSplitIntent("sp2")
491		if in.Status != SplitInvalid {
492			t.Fatalf("intent must be invalid after initiator deactivated: %+v", in)
493		}
494	}
495	
496	func TestSplitIntentExpiry(t *testing.T) {
497		r := mustCreate(t, tempDir(t))
498		intentWorld(t, r)
499		base := time.Unix(2_000_000_000, 0)
500		r.now = func() time.Time { return base }
501		defer func() { r.now = time.Now }()
502	
503		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp1")); err != nil {
504			t.Fatal(err)
505		}
506		// 到期前一刻仍有效
507		r.now = func() time.Time { return base.Add(time.Hour - time.Nanosecond) }
508		in, _ := r.GetSplitIntent("sp1")
509		if in.Status != SplitPending {
510			t.Fatalf("before expiry must be pending: %+v", in)
511		}
512		// 从到期时间点起过期
513		r.now = func() time.Time { return base.Add(time.Hour) }
514		in, _ = r.GetSplitIntent("sp1")
515		if in.Status != SplitExpired {
516			t.Fatalf("at expiry must be expired: %+v", in)
517		}
518		if _, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", true)); !errors.Is(err, ErrSplitIntentExpired) {
519			t.Fatalf("answer on expired: %v", err)
520		}
521		if _, err := r.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-1")); !errors.Is(err, ErrSplitIntentExpired) {
522			t.Fatalf("withdraw on expired: %v", err)
523		}
524		// 过期后可用新编号另建方案
525		if _, err := r.CreateSplitIntent(createIntentReq(r, "sp2")); err != nil {
526			t.Fatalf("new intent after expiry: %v", err)
527		}
528	}
529	
530	// ---- 幂等 ----
531	
532	func TestSplitIntentIdempotency(t *testing.T) {
533		r := mustCreate(t, tempDir(t))
534		intentWorld(t, r)
535	
536		req := createIntentReq(r, "sp1")
537		res, err := r.CreateSplitIntent(req)
538		if err != nil || res.Replayed {
539			t.Fatalf("first create: %+v %v", res, err)
540		}
541		// 相同内容重提回放首次成功；仅调整份额名单排列视为相同内容
542		dup := req
543		dup.Shares = []SplitShare{
544			{AccountID: "carol", Share: 2000},
545			{AccountID: "alice", Share: 5000},
546			{AccountID: "bob", Share: 3000},
547		}
548		res, err = r.CreateSplitIntent(dup)
549		if err != nil || !res.Replayed || res.IntentID != "sp1" || res.Status != SplitPending {
550			t.Fatalf("reordered replay: %+v %v", res, err)
551		}
552		// 改内容报请求号冲突
553		conflict := req
554		conflict.Reason = "换个原因"
555		if _, err := r.CreateSplitIntent(conflict); !errors.Is(err, ErrRequestConflict) {
556			t.Fatalf("changed reason: %v", err)
557		}
558		// 答复幂等
559		ans := answerReq("bob", "sp1", "ans-bob", true)
560		if _, err := r.AnswerSplitIntent(ans); err != nil {
561			t.Fatal(err)
562		}
563		res2, err := r.AnswerSplitIntent(ans)
564		if err != nil || !res2.Replayed || res2.Status != SplitPending {
565			t.Fatalf("answer replay: %+v %v", res2, err)
566		}
567		ans.Agree = false
568		if _, err := r.AnswerSplitIntent(ans); !errors.Is(err, ErrRequestConflict) {
569			t.Fatalf("changed answer: %v", err)
570		}
571		// 撤回幂等
572		wd := withdrawReq("alice", "sp1", "wd-1")
573		if _, err := r.WithdrawSplitIntent(wd); err != nil {
574			t.Fatal(err)
575		}
576		res3, err := r.WithdrawSplitIntent(wd)
577		if err != nil || !res3.Replayed || res3.Status != SplitWithdrawn {
578			t.Fatalf("withdraw replay: %+v %v", res3, err)
579		}
580		wd.Reason = "换个理由"
581		if _, err := r.WithdrawSplitIntent(wd); !errors.Is(err, ErrRequestConflict) {
582			t.Fatalf("changed withdraw reason: %v", err)
583		}
584		// 意向操作与既有操作共用请求号范围
585		if _, err := r.Issue(IssueRequest{
586			Operator: "alice", Reason: "首发", RequestID: "create-sp1",
587			ItemID: "i9", SeriesID: "s1", BatchNo: "b1", HolderID: "alice",
588		}); !errors.Is(err, ErrRequestConflict) {
589			t.Fatalf("request id shared with issue: %v", err)
590		}
