593	func TestSplitIntentConcurrentDuplicate(t *testing.T) {
594		r := mustCreate(t, tempDir(t))
595		intentWorld(t, r)
596	
597		// 并发重复创建同一请求只生效一次
598		const n = 8
599		var wg sync.WaitGroup
600		results := make([]CreateSplitIntentResult, n)
601		for i := 0; i < n; i++ {
602			wg.Add(1)
603			go func(i int) {
604				defer wg.Done()
605				res, _ := r.CreateSplitIntent(createIntentReq(r, "sp1"))
606				results[i] = res
607			}(i)
608		}
609		wg.Wait()
610		succeeded := 0
611		for _, res := range results {
612			if res.Err == nil {
613				succeeded++
614			}
615		}
616		if succeeded != n {
617			t.Fatalf("all duplicates must return first success, got %d/%d", succeeded, n)
618		}
619		evs, _ := r.SplitIntentHistory("i1")
620		if len(evs) != 1 {
621			t.Fatalf("concurrent create must produce exactly one event: %d", len(evs))
622		}
623		// 并发重复答复只记录一次
624		for i := 0; i < n; i++ {
625			wg.Add(1)
626			go func() {
627				defer wg.Done()
628				_, _ = r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", true))
629			}()
630		}
631		wg.Wait()
632		evs, _ = r.SplitIntentHistory("i1")
633		if len(evs) != 2 {
634			t.Fatalf("concurrent answer must produce exactly one answer event: %d", len(evs))
635		}
636	}
