638	// ---- 持久化 ----
639	
640	func TestSplitIntentPersistence(t *testing.T) {
641		dir := tempDir(t)
642		r := mustCreate(t, dir)
643		intentWorld(t, r)
644		createReq := createIntentReq(r, "sp1")
645		if _, err := r.CreateSplitIntent(createReq); err != nil {
646			t.Fatal(err)
647		}
648		if _, err := r.AnswerSplitIntent(answerReq("bob", "sp1", "ans-bob", true)); err != nil {
649			t.Fatal(err)
650		}
651		if _, err := r.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-1")); err != nil {
652			t.Fatal(err)
653		}
654		if err := r.Close(); err != nil {
655			t.Fatal(err)
656		}
657	
658		// 关闭重开后方案、答复、历史与请求结果完整保留
659		r2, err := Open(dir)
