661			t.Fatalf("reopen: %v", err)
662		}
663		defer r2.Close()
664		in, err := r2.GetSplitIntent("sp1")
665		if err != nil || in.Status != SplitWithdrawn || len(in.Shares) != 3 {
666			t.Fatalf("intent after reopen: %+v %v", in, err)
667		}
668		if in.Shares[0].Answer != SplitAnswerAgree || in.Shares[1].Answer != SplitAnswerAgree ||
669			in.Shares[2].Answer != "" {
670			t.Fatalf("answers after reopen: %+v", in.Shares)
671		}
672		evs, err := r2.SplitIntentHistory("i1")
673		if err != nil || len(evs) != 3 {
674			t.Fatalf("history after reopen: %+v %v", evs, err)
675		}
676		if evs[0].Kind != "create" || evs[1].Kind != "answer" || evs[2].Kind != "withdraw" {
677			t.Fatalf("event order after reopen: %+v", evs)
678		}
679		// 旧请求重放（同一请求内容）
680		res, err := r2.CreateSplitIntent(createReq)
681		if err != nil || !res.Replayed || res.Status != SplitPending {
682			t.Fatalf("create replay after reopen: %+v %v", res, err)
683		}
684		res2, err := r2.WithdrawSplitIntent(withdrawReq("alice", "sp1", "wd-1"))
685		if err != nil || !res2.Replayed || res2.Status != SplitWithdrawn {
686			t.Fatalf("withdraw replay after reopen: %+v %v", res2, err)
687		}
688	}
689	
690	// 手写一份引入拆分意向之前的旧格式快照（没有 intents 等新字段）：旧登记册
691	// 必须能直接打开，意向查询按不存在处理，新意向可正常创建。
