1	package registry
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7		"strings"
8		"time"
9	)
10	
11	// ---- 藏品拆分意向 ----
12	//
13	// 拆分意向只记录各方对未来拆分分配方案的约定：创建、答复与撤回都不改变
14	// 藏品编号、持有人、持有版本与版税应付，既有发行、转让与代转功能不受
15	// 影响。意向在创建时绑定持有版本；持有版本变化或发起人、任一参与账户
16	// 停用后意向失效（派生状态，不落盘），未失效时从到期时间点起过期。
17	
18	// normalizeSplitShares 校验并规范化分配方案：至少两个账户、账户不重复、
19	// 每份 1..10000、合计恰好 10000，并按账户排序，使同一方案与书写顺序
20	// 无关（仅调整名单排列视为相同内容）。均为无状态的参数校验；不合法时
21	// 返回 ErrInvalidArgument，不占用请求号。
22	func normalizeSplitShares(shares []SplitShare) ([]intentShare, error) {
23		if len(shares) < 2 {
24			return nil, fmt.Errorf("%w: 分配方案至少需要两个账户", ErrInvalidArgument)
25		}
26		seen := make(map[string]bool, len(shares))
27		out := make([]intentShare, 0, len(shares))
28		var total int64
29		for _, sh := range shares {
30			if strings.TrimSpace(sh.AccountID) == "" {
31				return nil, fmt.Errorf("%w: 参与账户不能为空", ErrInvalidArgument)
32			}
33			if sh.Share < 1 || sh.Share > RoyaltyRateBase {
34				return nil, fmt.Errorf("%w: 账户 %s 的份额 %d 不在 1..%d 内",
35					ErrInvalidArgument, sh.AccountID, sh.Share, RoyaltyRateBase)
36			}
37			if seen[sh.AccountID] {
38				return nil, fmt.Errorf("%w: 参与账户 %s 重复", ErrInvalidArgument, sh.AccountID)
39			}
40			seen[sh.AccountID] = true
41			total += sh.Share
42			out = append(out, intentShare{AccountID: sh.AccountID, Share: sh.Share})
43		}
44		if total != RoyaltyRateBase {
45			return nil, fmt.Errorf("%w: 份额合计 %d 必须等于 %d", ErrInvalidArgument, total, RoyaltyRateBase)
46		}
47		sort.Slice(out, func(i, j int) bool { return out[i].AccountID < out[j].AccountID })
48		return out, nil
49	}
50	
51	// intentBaseStatus 由各方答复计算未终结意向的基础状态：全部同意为
52	// 已达成，否则为待确认。
53	func intentBaseStatus(rec intentRec) string {
54		for _, sh := range rec.Shares {
55			if sh.Answer != SplitAnswerAgree {
56				return SplitPending
57			}
58		}
59		return SplitAgreed
60	}
61	
62	// intentCurrentStatus 计算意向当前状态。拒绝与撤回是落盘的终态；失效
63	// （持有版本变化，或发起人、任一参与账户停用）与过期不单独落盘，按当前
64	// 状态与时间实时判断，失效优先于过期。调用时需持有锁。
65	func (r *Registry) intentCurrentStatus(rec intentRec, now time.Time) string {
66		switch rec.Status {
67		case "rejected":
68			return SplitRejected
69		case "withdrawn":
70			return SplitWithdrawn
71		}
72		h, ok := r.state.Holdings[rec.ItemID]
73		if !ok || h.Version != rec.GrantVer {
74			// 持有版本单调递增，藏品即使转回原持有人也不会回到旧版本，
75			// 失效据此不可恢复。
76			return SplitInvalid
77		}
78		if a, ok := r.state.Accounts[rec.InitiatorID]; !ok || !a.Active {
79			return SplitInvalid
80		}
81		for _, sh := range rec.Shares {
82			if a, ok := r.state.Accounts[sh.AccountID]; !ok || !a.Active {
83				return SplitInvalid
84			}
85		}
86		if !rec.ExpiresAt.IsZero() && !now.Before(rec.ExpiresAt) {
87			return SplitExpired
88		}
89		return intentBaseStatus(rec)
90	}
