312	func (r *Registry) replayCreateIntent(prev request, sig string) (CreateSplitIntentResult, error) {
313		if prev.Kind != "intent_create" || prev.Params != sig {
314			return CreateSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
315				ErrRequestConflict, prev.Operator, prev.RequestID)
316		}
317		res := CreateSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status,
318			GrantVer: prev.Version, Replayed: true}
319		if prev.Rejected {
320			res.Err = codeErr(prev.Reason)
321			res.Status = ""
322			res.GrantVer = 0
323			return res, res.Err
324		}
325		return res, nil
326	}
327	
328	func answerIntentParamsSig(req AnswerSplitIntentRequest) string {
329		b, _ := json.Marshal(struct {
330			Kind     string `json:"kind"`
331			IntentID string `json:"intent_id"`
332			Agree    bool   `json:"agree"`
333			Reason   string `json:"reason"`
334		}{"intent_answer", req.IntentID, req.Agree, req.Reason})
335		return string(b)
336	}
337	
338	// AnswerSplitIntent 由方案中的参与账户答复自己的份额（同意或拒绝）。
339	// 意向待确认或已达成且仍有效时才能答复：全部同意则意向显示已达成，
340	// 任一拒绝则显示已拒绝。重复相同答复成功但不新增记录；已答复后改答
341	// 拒绝（ErrSplitAnswered）。名单外账户无权答复（ErrForbidden）；已拒绝、
342	// 已撤回、已失效或已过期的意向不再接受答复，分别明确拒绝。发起人列入
343	// 方案时创建即视为已同意，再作不同答复按改答拒绝。
344	//
345	// 请求号语义与其他操作一致：相同参数重提回放首次结果，参数不同返回
346	// ErrRequestConflict；参数错误与引用不存在不占用请求号。
347	//
348	// 一次答复是否生效始终以保存完成为准：本次答复（同意或拒绝）、意向终结
349	// 状态、意向历史与请求结果尚未写入原登记册而保存失败时，返回实际保存
350	// 错误，不返回成功，也不用随后读取数据的错误或原业务拒绝替代它；结果
351	// 为空（无意向编号、无状态、业务错误为空、不标回放），请求号与意向历史
352	// 序号都不被这次未保存的答复消耗。即使失败后原数据暂时无法读取、状态未
353	// 能按磁盘重建，同一个仍打开的登记册中各方此前已保存的答复、份额与意向
354	// 结束时间仍保持原样，意向状态继续按原有答复、当前持有与账户状态及当前
355	// 时间判断，意向历史不出现这次答复；后续其他操作成功保存也不会把这次
356	// 未保存的答复或终结状态带入登记册。保存条件恢复后用原请求号和相同内容
357	// 重提，按当时的意向状态重新处理（首次重新成功不标回放；意向此时已过期
358	// 或失效则沿用现有对应拒绝），真正保存成功后相同请求才回放首次结果。
359	func (r *Registry) AnswerSplitIntent(req AnswerSplitIntentRequest) (AnswerSplitIntentResult, error) {
360		missing := []string{}
361		if strings.TrimSpace(req.Operator) == "" {
362			missing = append(missing, "operator")
363		}
364		if strings.TrimSpace(req.Reason) == "" {
365			missing = append(missing, "reason")
366		}
367		if strings.TrimSpace(req.RequestID) == "" {
368			missing = append(missing, "request_id")
369		}
370		if strings.TrimSpace(req.IntentID) == "" {
371			missing = append(missing, "intent_id")
372		}
373		if len(missing) > 0 {
374			return AnswerSplitIntentResult{}, fmt.Errorf("%w: 答复拆分意向请求缺少必填字段 %s",
375				ErrInvalidArgument, strings.Join(missing, ", "))
376		}
377		r.mu.Lock()
378		defer r.mu.Unlock()
379		if err := r.checkOpen(); err != nil {
380			return AnswerSplitIntentResult{}, err
381		}
382	
383		now := r.now()
384		key := requestKey(req.Operator, req.RequestID)
385		sig := answerIntentParamsSig(req)
386		if prev, ok := r.state.Requests[key]; ok {
387			return r.replayAnswerIntent(prev, sig)
388		}
389	
390		rec, ok := r.state.Intents[req.IntentID]
391		if !ok {
392			// 引用不存在不占用请求号。
393			err := fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, req.IntentID)
394			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: err}, err
395		}
396		idx := -1
397		for i, sh := range rec.Shares {
398			if sh.AccountID == req.Operator {
399				idx = i
400				break
401			}
402		}
403		if idx < 0 {
404			bizErr := fmt.Errorf("%w: 账户 %s 不在意向 %s 的分配方案中",
405				ErrForbidden, req.Operator, req.IntentID)
406			if err := r.saveIntentRequestRejection(key, sig, req.Operator, req.RequestID,
407				"intent_answer", req.IntentID, bizErr); err != nil {
408				return AnswerSplitIntentResult{}, err
409			}
410			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
411		}
412		answer := SplitAnswerReject
413		if req.Agree {
414			answer = SplitAnswerAgree
415		}
416		// 已终结、已失效或已过期的意向不再接受答复，分别说明原因。
417		switch status := r.intentCurrentStatus(rec, now); status {
418		case SplitRejected, SplitWithdrawn, SplitInvalid, SplitExpired:
419			bizErr := intentEndedErr(status, req.IntentID)
420			if err := r.saveIntentRequestRejection(key, sig, req.Operator, req.RequestID,
421				"intent_answer", req.IntentID, bizErr); err != nil {
422				return AnswerSplitIntentResult{}, err
423			}
424			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
425		}
426		if prev := rec.Shares[idx].Answer; prev != "" {
427			if prev == answer {
428				// 重复相同答复：成功但不新增变更记录；该请求号仍登记为成功，
429				// 相同请求重放回放同一结果。
430				status := r.intentCurrentStatus(rec, now)
431				r.state.Requests[key] = request{
432					Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_answer",
433					Params: sig, IntentID: req.IntentID, Status: status,
434				}
435				if err := r.commit(); err != nil {
436					// 这次重复答复只登记请求结果、不改动意向与历史；保存失败且
437					// 状态未能按磁盘重建时，显式撤销未保存的请求号占用，整体
438					// 返回空结果与实际保存错误。
439					delete(r.state.Requests, key)
440					return AnswerSplitIntentResult{}, err
441				}
442				return AnswerSplitIntentResult{IntentID: req.IntentID, Status: status}, nil
443			}
444			// 已答复后改答拒绝。
445			bizErr := fmt.Errorf("%w: 账户 %s 已答复 %s，不能改为 %s",
446				ErrSplitAnswered, req.Operator, prev, answer)
447			if err := r.saveIntentRequestRejection(key, sig, req.Operator, req.RequestID,
448				"intent_answer", req.IntentID, bizErr); err != nil {
449				return AnswerSplitIntentResult{}, err
450			}
451			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
452		}
453	
454		from := r.intentCurrentStatus(rec, now)
455		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
456		// 未保存的答复、意向终结状态、答复记录与请求号占用都必须显式撤销，
457		// 否则随后查询会把这次答复当作已生效，后续任何一次成功保存还会把这份
458		// 未保存的答复与终结状态带进登记册。
459		prevIntentSeq := r.state.NextIntentSeq
460		prevEvents := len(r.state.IntentEvents)
461		prevRec := rec
462		// rec.Shares 与 prevRec 共享底层数组，先复制再改，回滚副本才能保留
463		// 提交前各方已保存的答复。
464		rec.Shares = append([]intentShare(nil), rec.Shares...)
465		rec.Shares[idx].Answer = answer
466		if answer == SplitAnswerReject {
467			// 任一参与账户拒绝即终结为已拒绝（落盘终态）。
468			rec.Status = "rejected"
469			rec.EndedAt = now
470		}
471		r.state.Intents[req.IntentID] = rec
472		to := r.intentCurrentStatus(rec, now)
473		seq := prevIntentSeq + 1
474		r.state.NextIntentSeq = seq
475		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
476			Seq: seq, IntentID: req.IntentID, ItemID: rec.ItemID, Kind: "answer",
477			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
478			Answer: answer, FromStatus: from, ToStatus: to, OccurredAt: now,
479		})
480		r.state.Requests[key] = request{
481			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_answer",
482			Params: sig, IntentID: req.IntentID, Status: to,
483		}
484		if err := r.commit(); err != nil {
485			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随旧
486			// 状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、状态
487			// 未能重建时请求记录仍在，据此把本次未保存的改动全部撤销——意向
488			// 恢复为提交前的答复、份额与结束时间，历史与序号回退，请求号释放。
489			if _, ok := r.state.Requests[key]; ok {
490				delete(r.state.Requests, key)
491				r.state.Intents[req.IntentID] = prevRec
492				r.state.IntentEvents = r.state.IntentEvents[:prevEvents]
493				r.state.NextIntentSeq = prevIntentSeq
494			}
495			return AnswerSplitIntentResult{}, err
496		}
497		return AnswerSplitIntentResult{IntentID: req.IntentID, Status: to}, nil
498	}
499	
500	// intentEndedErr 构造意向已终结、失效或过期时的拒绝原因。
501	func intentEndedErr(status, intentID string) error {
502		switch status {
503		case SplitRejected:
504			return fmt.Errorf("%w: 拆分意向 %s 已拒绝，不再接受答复或撤回", ErrSplitIntentRejected, intentID)
505		case SplitWithdrawn:
506			return fmt.Errorf("%w: 拆分意向 %s 已撤回，不再接受答复", ErrSplitIntentWithdrawn, intentID)
507		case SplitInvalid:
508			return fmt.Errorf("%w: 拆分意向 %s 已失效（持有版本变化或参与账户停用）", ErrSplitIntentInvalid, intentID)
509		default:
510			return fmt.Errorf("%w: 拆分意向 %s 已过期", ErrSplitIntentExpired, intentID)
511		}
512	}
513	
514	// recordIntentRequest 记录意向类操作的状态类业务拒绝并尽力落盘。
515	func (r *Registry) recordIntentRequest(key, sig, operator, requestID, kind, intentID string, bizErr error) {
516		r.state.Requests[key] = request{
517			Operator: operator, RequestID: requestID, Kind: kind,
518			Params: sig, Rejected: true, Reason: errCode(bizErr), IntentID: intentID,
519		}
520		_ = r.commit()
521	}
522	
523	// saveIntentRequestRejection 登记意向类操作的状态类业务拒绝并落盘。与
524	// recordIntentRequest 不同：保存失败时撤销这次未保存的请求号占用并把实际
525	// 保存错误返回给调用者，绝不吞掉写入错误、也不让未保存的拒绝留在当前
526	// 登记册中。
527	func (r *Registry) saveIntentRequestRejection(key, sig, operator, requestID, kind, intentID string, bizErr error) error {
528		r.state.Requests[key] = request{
529			Operator: operator, RequestID: requestID, Kind: kind,
530			Params: sig, Rejected: true, Reason: errCode(bizErr), IntentID: intentID,
531		}
532		if err := r.commit(); err != nil {
533			// commit 失败时已尝试按磁盘内容重建状态；磁盘暂时不可读、状态未能
534			// 重建时请求记录仍在，显式撤销，使这次未保存的拒绝不占用请求号。
535			delete(r.state.Requests, key)
536			return err
537		}
538		return nil
539	}
540	
541	func (r *Registry) replayAnswerIntent(prev request, sig string) (AnswerSplitIntentResult, error) {
542		if prev.Kind != "intent_answer" || prev.Params != sig {
543			return AnswerSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
544				ErrRequestConflict, prev.Operator, prev.RequestID)
545		}
546		res := AnswerSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status, Replayed: true}
547		if prev.Rejected {
548			res.Err = codeErr(prev.Reason)
549			res.Status = ""
550			return res, res.Err
551		}
552		return res, nil
553	}
554	
555	func withdrawIntentParamsSig(req WithdrawSplitIntentRequest) string {
556		b, _ := json.Marshal(struct {
557			Kind     string `json:"kind"`
558			IntentID string `json:"intent_id"`
559			Reason   string `json:"reason"`
560		}{"intent_withdraw", req.IntentID, req.Reason})
561		return string(b)
562	}
563	
564	// WithdrawSplitIntent 由发起人撤回仍有效的待确认或已达成意向。仅发起人
565	// 可撤回（ErrForbidden）；已拒绝的意向不能撤回（ErrSplitIntentRejected），
566	// 已失效或已过期的意向拒绝撤回并说明原因；已撤回后再次撤回成功但不新增
567	// 记录（幂等）。请求号语义与其他操作一致。
568	func (r *Registry) WithdrawSplitIntent(req WithdrawSplitIntentRequest) (WithdrawSplitIntentResult, error) {
569		missing := []string{}
570		if strings.TrimSpace(req.Operator) == "" {
571			missing = append(missing, "operator")
572		}
573		if strings.TrimSpace(req.Reason) == "" {
574			missing = append(missing, "reason")
575		}
576		if strings.TrimSpace(req.RequestID) == "" {
577			missing = append(missing, "request_id")
578		}
579		if strings.TrimSpace(req.IntentID) == "" {
580			missing = append(missing, "intent_id")
581		}
582		if len(missing) > 0 {
583			return WithdrawSplitIntentResult{}, fmt.Errorf("%w: 撤回拆分意向请求缺少必填字段 %s",
584				ErrInvalidArgument, strings.Join(missing, ", "))
585		}
586		r.mu.Lock()
587		defer r.mu.Unlock()
588		if err := r.checkOpen(); err != nil {
589			return WithdrawSplitIntentResult{}, err
590		}
591	
592		now := r.now()
593		key := requestKey(req.Operator, req.RequestID)
594		sig := withdrawIntentParamsSig(req)
595		if prev, ok := r.state.Requests[key]; ok {
596			return r.replayWithdrawIntent(prev, sig)
597		}
598	
599		rec, ok := r.state.Intents[req.IntentID]
600		if !ok {
601			// 引用不存在不占用请求号。
602			err := fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, req.IntentID)
603			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: err}, err
604		}
605		if rec.InitiatorID != req.Operator {
606			bizErr := fmt.Errorf("%w: 只有发起人 %s 可以撤回意向 %s",
607				ErrForbidden, rec.InitiatorID, req.IntentID)
608			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_withdraw", req.IntentID, bizErr)
609			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
610		}
611		status := r.intentCurrentStatus(rec, now)
612		switch status {
613		case SplitWithdrawn:
614			// 已撤回是幂等终态：不新增变更记录；该请求号仍登记为成功。
615			r.state.Requests[key] = request{
616				Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_withdraw",
617				Params: sig, IntentID: req.IntentID, Status: SplitWithdrawn,
618			}
619			if err := r.commit(); err != nil {
620				return WithdrawSplitIntentResult{}, err
621			}
622			return WithdrawSplitIntentResult{IntentID: req.IntentID, Status: SplitWithdrawn}, nil
623		case SplitRejected, SplitInvalid, SplitExpired:
624			bizErr := intentEndedErr(status, req.IntentID)
625			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_withdraw", req.IntentID, bizErr)
626			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
627		}
628	
629		rec.Status = "withdrawn"
630		rec.EndedAt = now
631		r.state.Intents[req.IntentID] = rec
632		seq := r.state.NextIntentSeq + 1
633		r.state.NextIntentSeq = seq
634		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
635			Seq: seq, IntentID: req.IntentID, ItemID: rec.ItemID, Kind: "withdraw",
636			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
637			FromStatus: status, ToStatus: SplitWithdrawn, OccurredAt: now,
638		})
639		r.state.Requests[key] = request{
640			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_withdraw",
641			Params: sig, IntentID: req.IntentID, Status: SplitWithdrawn,
642		}
643		if err := r.commit(); err != nil {
644			return WithdrawSplitIntentResult{}, err
645		}
646		return WithdrawSplitIntentResult{IntentID: req.IntentID, Status: SplitWithdrawn}, nil
647	}
648	
649	func (r *Registry) replayWithdrawIntent(prev request, sig string) (WithdrawSplitIntentResult, error) {
650		if prev.Kind != "intent_withdraw" || prev.Params != sig {
651			return WithdrawSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
652				ErrRequestConflict, prev.Operator, prev.RequestID)
653		}
654		res := WithdrawSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status, Replayed: true}
655		if prev.Rejected {
656			res.Err = codeErr(prev.Reason)
657			res.Status = ""
658			return res, res.Err
659		}
660		return res, nil
661	}
662	
663	// ---- 拆分意向查询 ----
664	
665	// GetSplitIntent 按编号查询拆分意向的方案、各方答复与当前状态。意向不
666	// 存在时返回包裹 ErrNotFound 的错误；返回的 Status 按当前持有、账户
667	// 状态与时间实时计算（已失效、已过期为派生状态）。已结束的意向仍可
668	// 查询。
669	func (r *Registry) GetSplitIntent(intentID string) (SplitIntent, error) {
670		r.mu.Lock()
671		defer r.mu.Unlock()
672		if err := r.checkOpen(); err != nil {
673			return SplitIntent{}, err
674		}
675		rec, ok := r.state.Intents[intentID]
676		if !ok {
677			return SplitIntent{}, fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, intentID)
678		}
679		parties := make([]SplitParty, 0, len(rec.Shares))
680		for _, sh := range rec.Shares {
681			parties = append(parties, SplitParty{
682				AccountID: sh.AccountID, Share: sh.Share, Answer: sh.Answer,
683			})
684		}
685		return SplitIntent{
686			ID: rec.ID, ItemID: rec.ItemID, InitiatorID: rec.InitiatorID,
687			Shares: parties, GrantVer: rec.GrantVer, ExpiresAt: rec.ExpiresAt,
688			Status:    r.intentCurrentStatus(rec, r.now()),
689			CreatedAt: rec.CreatedAt, EndedAt: rec.EndedAt,
690		}, nil
691	}
692	
693	// SplitIntentHistory 按藏品查看拆分意向变更记录（创建、首次答复、撤回），
694	// 按发生先后排列；每条记录包含意向编号、操作者、原因、请求号、发生时间
695	// 与前后状态。藏品不存在时返回包裹 ErrNotFound 的错误。
696	func (r *Registry) SplitIntentHistory(itemID string) ([]SplitIntentEvent, error) {
697		r.mu.Lock()
698		defer r.mu.Unlock()
699		if err := r.checkOpen(); err != nil {
700			return nil, err
701		}
702		if _, ok := r.state.Items[itemID]; !ok {
703			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
704		}
705		out := make([]SplitIntentEvent, 0)
706		for _, e := range r.state.IntentEvents {
707			if e.ItemID != itemID {
708				continue
709			}
710			out = append(out, SplitIntentEvent{
711				Seq: e.Seq, IntentID: e.IntentID, ItemID: e.ItemID, Kind: e.Kind,
712				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
713				Answer: e.Answer, FromStatus: e.FromStatus, ToStatus: e.ToStatus,
714				OccurredAt: e.OccurredAt,
715			})
716		}
717		return out, nil
718	}
